/**
 * The POLUTEK lockup as outlined SVG paths: a flat play badge (blue rounded rectangle, white triangle), then the POLUTEK
 * wordmark. No web font, no <text>, crisp at any DPR. (The accessible name stays "POLUTEK.COM", the site's name.)
 *
 * Artwork: the letters are modified outlines of Nunito (SIL Open Font License 1.1, notice in
 * public/brand/NOTICE-Nunito-OFL.txt), generated by scripts/brand/generate-wordmark.py into
 * ./polutek-wordmark-paths.ts. "POLUTEK" is drawn in dark navy (--brand-navy, #0A2342); the badge uses --chan-blue, the Subscribe
 * button colour. The viewBox ends at the right edge of the K (no empty margin). Standalone copies: public/brand/polutek-wordmark*.svg.
 *
 * Sizing is height-driven: pass a height class. The full lockup's viewBox is 120 units tall for a
 * 100-unit cap height, so `h-[21px]` gives a 17.5px cap height; without the badge the viewBox is
 * 102.4 units tall. On phones narrower than 350px the default shrinks to 18px so the lockup stays clear of the
 * search, bell and avatar buttons.
 *
 * Header height: this svg never decides the height of the top bar. It is `display: block` (no inline
 * baseline gap), has a fixed height from its class (21px phones, 25px md+, both below the 38px of the
 * bar's content row), no margin or padding, and its link is a 44px touch target pulled back with
 * -my-[3px] so the bar still gets 38px from it (tests/unit/components/navbar-logo-height.test.tsx).
 */
import { cn } from "@/lib/utils";
import {
  BADGE_PATH,
  INK_PATH,
  PLAY_PATH,
  WORDMARK_TEXT_X,
  WORDMARK_VIEWBOX_FULL,
  WORDMARK_VIEWBOX_TEXT,
} from "./polutek-wordmark-paths";

export default function PolutekWordmark({
  className,
  decorative = false,
  badge = true,
}: {
  className?: string;
  /** The parent already supplies the accessible name (for example a labelled link). */
  decorative?: boolean;
  /** The play badge to the left of the wordmark (default). */
  badge?: boolean;
}) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={badge ? WORDMARK_VIEWBOX_FULL : WORDMARK_VIEWBOX_TEXT}
      role={decorative ? undefined : "img"}
      aria-label={decorative ? undefined : "POLUTEK.COM"}
      aria-hidden={decorative ? true : undefined}
      focusable="false"
      data-brand-logo="wordmark"
      data-brand-badge={badge ? "true" : "false"}
      className={cn("m-0 block h-[21px] w-auto shrink-0 select-none overflow-visible p-0 max-[350px]:h-[18px] md:h-[25px]", className)}
    >
      {badge ? (
        <>
          <path style={{ fill: "var(--chan-blue, #2563eb)" }} d={BADGE_PATH} />
          <path fill="#fff" d={PLAY_PATH} />
        </>
      ) : null}
      <g transform={badge ? `translate(${WORDMARK_TEXT_X} 0)` : undefined}>
        <path style={{ fill: "var(--brand-navy, #0a2342)" }} d={INK_PATH} />
      </g>
    </svg>
  );
}
